WITH enriched AS (SELECT *, LAST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY status ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee, PERCENT_RANK() OVER (PARTITION BY status ORDER BY monthly_fee NULLS FIRST) AS monthly_fee_percent_rank, FIRST_VALUE(monthly_fee, TRUE) OVER (ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee FROM subscriptions) SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, last_known_monthly_fee FROM enriched ORDER BY start_date NULLS FIRST;
